CREATE OR REPLACE FUNCTION public.publish_report_price_checked(_key text,_values jsonb,_by uuid,_expected timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE at_time timestamptz;BEGIN IF NOT public.is_control(_by) OR NOT public.is_account_admin(_by) THEN RAISE EXCEPTION 'Control Admin only';END IF;SELECT updated_at INTO at_time FROM public.report_prices WHERE report_key=_key FOR UPDATE;IF at_time IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'This report changed. Reload before publishing.';END IF;IF EXISTS(SELECT 1 FROM public.report_price_changes WHERE report_key=_key AND status='scheduled') THEN RAISE EXCEPTION 'Cancel the scheduled change first';END IF;PERFORM public.apply_report_price_edit(_key,_values,_by);END $$;
REVOKE ALL ON FUNCTION public.publish_report_price_checked(text,jsonb,uuid,timestamptz) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.publish_report_price_checked(text,jsonb,uuid,timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.schedule_report_price_edit(_key text,_values jsonb,_by uuid,_at timestamptz,_expected timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old public.report_prices;BEGIN IF NOT public.is_control(_by) OR NOT public.is_account_admin(_by) THEN RAISE EXCEPTION 'Control Admin only';END IF;SELECT * INTO old FROM public.report_prices WHERE report_key=_key FOR UPDATE;IF old.updated_at IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'This report changed. Reload before publishing.';END IF;IF _at<=now() OR (_at AT TIME ZONE 'Asia/Bangkok')::time<>'00:00:00'::time THEN RAISE EXCEPTION 'Choose a future Bangkok midnight';END IF;INSERT INTO public.report_price_changes(report_key,new_values,effective_at,created_by) VALUES(_key,_values,_at,_by);INSERT INTO public.report_price_history(report_key,by_user,summary,changes) VALUES(_key,_by,'Scheduled for '||(_at AT TIME ZONE 'Asia/Bangkok')::date||': '||coalesce(_values->>'_summary','Report updated'),jsonb_build_object('old',to_jsonb(old),'new',_values));INSERT INTO public.security_events(user_id,event_type,details) VALUES(_by,'ROLE_CHANGE',jsonb_build_object('action','report_price_scheduled','report',_key,'values',_values,'effective_at',_at));END $$;
REVOKE ALL ON FUNCTION public.schedule_report_price_edit(text,jsonb,uuid,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.schedule_report_price_edit(text,jsonb,uuid,timestamptz,timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.cancel_report_price_change(_id uuid,_by uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.report_price_changes;BEGIN IF NOT public.is_control(_by) OR NOT public.is_account_admin(_by) THEN RAISE EXCEPTION 'Control Admin only';END IF;UPDATE public.report_price_changes SET status='cancelled' WHERE id=_id AND status='scheduled' RETURNING * INTO c;IF NOT FOUND THEN RAISE EXCEPTION 'Scheduled change unavailable';END IF;INSERT INTO public.report_price_history(report_key,by_user,summary,changes) VALUES(c.report_key,_by,'Scheduled change cancelled',c.new_values);INSERT INTO public.security_events(user_id,event_type,details) VALUES(_by,'ROLE_CHANGE',jsonb_build_object('action','report_price_cancelled','report',c.report_key));END $$;
REVOKE ALL ON FUNCTION public.cancel_report_price_change(uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.cancel_report_price_change(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.create_verification_report_order(_uid uuid,_company uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q jsonb;o public.verification_orders;BEGIN IF public.account_role_of(_uid)<>'seller' OR NOT public.verification_owner(_uid,_company) THEN RAISE EXCEPTION 'Not your company';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('report:'||_uid::text,0));IF EXISTS(SELECT 1 FROM public.company_verifications WHERE company_id=_company AND status='checking') THEN RETURN jsonb_build_object('existing',true);END IF;q:=public.report_quote(_uid,'verification');IF q->>'method'='Quote' THEN RAISE EXCEPTION 'Ask PitchSnack for a quote';END IF;IF q->>'method'='Plan' THEN INSERT INTO public.plan_usage(user_id,kind,ref,term_start) VALUES(_uid,'report:verification',_company::text,(q->>'quarterStart')::timestamptz);END IF;INSERT INTO public.verification_orders(company_id,ordered_by,amount,vat,total,method,status,paid_at) VALUES(_company,_uid,CASE WHEN q->>'method' IN ('Plan','Free period') THEN 0 ELSE (q->>'price')::numeric END,CASE WHEN q->>'method' IN ('Plan','Free period') THEN 0 ELSE round((q->>'price')::numeric*.07,2) END,(q->>'amount')::numeric,q->>'method','paid',now()) RETURNING * INTO o;INSERT INTO public.company_verifications(company_id,status,included,requested_by,started_at,ready_by) VALUES(_company,'checking',q->>'method' IN ('Plan','Free period'),_uid,now(),public.verification_business_due(now(),2)) ON CONFLICT(company_id) DO UPDATE SET status='checking',included=excluded.included,requested_by=_uid,started_at=now(),ready_by=excluded.ready_by;RETURN to_jsonb(o);END $$;
REVOKE ALL ON FUNCTION public.create_verification_report_order(uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.create_verification_report_order(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.plan_report_quarter_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;old_n integer;k text;delta jsonb:='{}';BEGIN IF NEW.new_values ? 'reports' THEN FOR r IN SELECT value FROM jsonb_array_elements(NEW.new_values->'reports') LOOP IF r ? 'free_per_quarter' THEN k:=r->>'report_key';IF NOT EXISTS(SELECT 1 FROM public.report_prices WHERE report_key=k) OR (r->>'free_per_quarter')::integer NOT BETWEEN 0 AND 20 THEN RAISE EXCEPTION 'Invalid quarterly report allowance';END IF;SELECT free_per_quarter INTO old_n FROM public.plan_reports WHERE plan_id=NEW.plan_id AND report_key=k;INSERT INTO public.plan_reports(plan_id,report_key,mode,free_per_quarter) VALUES(NEW.plan_id,k,'none',(r->>'free_per_quarter')::integer) ON CONFLICT(plan_id,report_key) DO UPDATE SET free_per_quarter=excluded.free_per_quarter;IF old_n IS DISTINCT FROM (r->>'free_per_quarter')::integer THEN INSERT INTO public.report_price_history(report_key,by_user,summary,changes) SELECT k,NEW.by_user,'Free · '||name||': '||coalesce(old_n,0)||' → '||(r->>'free_per_quarter')||' a quarter',jsonb_build_object('plan',NEW.plan_id,'old',old_n,'new',r->'free_per_quarter') FROM public.plans WHERE id=NEW.plan_id;delta:=delta||jsonb_build_object(k,r);END IF;END IF;END LOOP;END IF;IF delta<>'{}'::jsonb THEN INSERT INTO public.security_events(user_id,event_type,details) VALUES(NEW.by_user,'ROLE_CHANGE',jsonb_build_object('action','plan_report_allowances','plan',NEW.plan_id,'changes',delta));END IF;RETURN NEW;END $$;